#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.IO;
using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
public sealed class OttomanActivityCapture:MonoBehaviour
{
    string output;int checks;
    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Boot(){if(!Environment.GetCommandLineArgs().Contains("-ottoman-activity-capture"))return;Application.runInBackground=true;var dir=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/OttomanActivity"));Directory.CreateDirectory(dir);SaveGames.TestRoot=Path.Combine(dir,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.besieged.json");var go=new GameObject("Ottoman report verification");DontDestroyOnLoad(go);go.AddComponent<OttomanActivityCapture>().output=dir;}
    void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
    IEnumerator Start(){AudioListener.volume=0;var run=Run();while(true){object next=null;bool more=false;try{more=run.MoveNext();if(more)next=run.Current;}catch(Exception ex){File.WriteAllText(Path.Combine(output,"checks.txt"),"FAILED "+checks+"\n"+ex);Application.Quit(1);yield break;}if(!more)break;yield return next;}File.WriteAllText(Path.Combine(output,"checks.txt"),checks+" checks passed");Application.Quit(0);}
    IEnumerator Run(){yield return null;SaveMenu.StartCampaign(false);float end=Time.realtimeSinceStartup+30;while(!VariableSingleton.IsInitialized&&Time.realtimeSinceStartup<end)yield return null;yield return new WaitForSecondsRealtime(.4f);Check(VariableSingleton.IsInitialized,"campaign initialized");
        var ui=FindObjectOfType<AssaultUI>(true);var manager=FindObjectOfType<ManagerUI>(true);CouncilUI.For(manager).Hide();CampaignHUD.Instance.DismissReport();FindObjectOfType<EventUI>(true).gameObject.SetActive(false);manager.gameObject.SetActive(false);ui.gameObject.SetActive(false);
        var state=VariableSingleton.Instance.CaptureState();state.turn=VariableSingleton.EffectiveSiegeTurn+2;VariableSingleton.Instance.RestoreValidated(state);OttomanDirector.Ensure();VariableSingleton.SetInt("iOttExecutedTurn",VariableSingleton.Turn);
        VariableSingleton.ChangeFloat("fSiegeRamp",-VariableSingleton.GetFloatVariable("fSiegeRamp")+.4f);VariableSingleton.ChangeFloat("fMoat",-VariableSingleton.GetFloatVariable("fMoat")+.65f);VariableSingleton.SetInt("iOttHornWorks",55);VariableSingleton.SetInt("iOttChainDamage",20);VariableSingleton.ChangeBool("bBatteringRam",false);VariableSingleton.SetInt("iOttArrowScreens",1);AI.Instance.AIBuildTower();
        var snapshot=JsonUtility.ToJson(VariableSingleton.Instance.CaptureState());var rng=JsonUtility.ToJson(UnityEngine.Random.state);int last=-1;var seen=new bool[3];for(int i=0;i<60;i++){int art=OttomanActivityView.NextArtwork();Check(art!=last,"no immediate repeated illustration");last=art;seen[art]=true;}Check(seen.All(x=>x),"all three illustrations selected");Check(rng==JsonUtility.ToJson(UnityEngine.Random.state),"art does not consume gameplay RNG");Check(snapshot==JsonUtility.ToJson(VariableSingleton.Instance.CaptureState()),"art does not mutate campaign");
        ui.gameObject.SetActive(true);yield return null;var panel=GameObject.Find("Ottoman activity report");Check(panel!=null,"live presenter attached");var progress=OttomanActivityView.Progress();Check(Mathf.Abs(progress[0]-.4f)<.001f&&progress[1]==1&&progress[2]==0&&progress[3]==1&&progress[4]==.55f&&progress[5]==.2f&&progress[6]==.65f,"actual engine and work states");
        foreach(int width in new[]{1280,1600}){Screen.SetResolution(width,width==1280?720:900,false);yield return new WaitForSecondsRealtime(1.5f);end=Time.realtimeSinceStartup+5;while(Screen.width!=width&&Time.realtimeSinceStartup<end)yield return null;Check(Screen.width==width,"actual capture width "+width);Canvas.ForceUpdateCanvases();foreach(var text in panel.GetComponentsInChildren<TMP_Text>())if(text.transform.parent.name!="Daily report viewport")Check(!text.isTextOverflowing,"caption fits: "+text.text);var corners=new Vector3[4];panel.GetComponent<RectTransform>().GetWorldCorners(corners);Check(corners[0].x>Screen.width*.5f,"report stays right");var title=panel.GetComponentsInChildren<TMP_Text>().First(t=>t.text=="OTTOMAN SIEGE ACTIVITY");title.rectTransform.GetWorldCorners(corners);Check(corners[2].y<Screen.height*.88f,"heading below top bar");var painting=ui.GetComponentsInChildren<RawImage>().Single(r=>r.name=="Ottoman siege painting");foreach(string path in OttomanActivityView.ArtPaths){painting.texture=Resources.Load<Texture2D>(path);Check(painting.texture!=null,"art installed "+path);yield return Capture(width+"-"+path.Split('/').Last());}}
        var daily=panel.GetComponentsInChildren<ScrollRect>().Single();var savedReport=AI.Instance.LastReport;var setter=typeof(AI).GetProperty("LastReport").GetSetMethod(true);setter.Invoke(AI.Instance,new object[]{string.Join("\n\n",Enumerable.Repeat("Ottoman labourers carry timber to the works. The watch follows their movements beyond the moat.",30))});typeof(AssaultUI).GetMethod("RefreshReport",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).Invoke(ui,null);yield return null;Canvas.ForceUpdateCanvases();Check(daily.content.rect.height>daily.viewport.rect.height,"long reports scroll inside the panel");daily.verticalNormalizedPosition=0;yield return null;Check(daily.viewport.GetComponent<RectMask2D>()!=null&&daily.verticalNormalizedPosition<.01f,"report can be read to the end within clipping boundary");yield return Capture("1600-long-report");setter.Invoke(AI.Instance,new object[]{savedReport});
        var turn=VariableSingleton.Turn;panel.GetComponentInChildren<Button>().onClick.Invoke();yield return null;Check(VariableSingleton.Turn==turn+1&&manager.gameObject.activeSelf&&!ui.gameObject.activeSelf,"quiet-day callback advances exactly one day and returns council");
        manager.gameObject.SetActive(false);CouncilUI.For(manager).Hide();CampaignHUD.Instance.DismissReport();VariableSingleton.SetInt("iBazouks",10000);AI.Instance.AIBashiBazoukAssault();Check(AI.Instance.HasPendingPhased,"real phased assault prepared");VariableSingleton.SetInt("iOttExecutedTurn",VariableSingleton.Turn);ui.gameObject.SetActive(true);yield return null;panel=GameObject.Find("Ottoman activity report");Check(panel.GetComponentInChildren<Button>().GetComponentInChildren<TMP_Text>().text=="Prepare the defence","assault-specific action caption");turn=VariableSingleton.Turn;panel.GetComponentInChildren<Button>().onClick.Invoke();yield return null;Check(PhasedAssaultUI.Current!=null&&PhasedAssaultUI.Current.Battle==AI.Instance.PendingPhased&&VariableSingleton.Turn==turn,"assault callback opens existing command sequence without advancing day");Check(!panel.activeSelf,"report hidden behind assault");
    }
    IEnumerator Capture(string name){yield return null;Canvas.ForceUpdateCanvases();var go=new GameObject("Capture camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.nearClipPlane=.1f;camera.farClipPlane=100;var canvases=FindObjectsOfType<Canvas>().Where(c=>c.isRootCanvas).ToArray();var modes=canvases.Select(c=>c.renderMode).ToArray();var cams=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24);var prior=RenderTexture.active;Texture2D shot=null;try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=10;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;shot=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);shot.ReadPixels(new Rect(0,0,target.width,target.height),0,0);shot.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),shot.EncodeToPNG());}finally{RenderTexture.active=prior;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=modes[i];canvases[i].worldCamera=cams[i];canvases[i].planeDistance=distances[i];}camera.targetTexture=null;RenderTexture.ReleaseTemporary(target);if(shot!=null)Destroy(shot);Destroy(go);}}
}
#endif
